package in.asmj.ride.model;
import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.mapping.Document;import java.util.ArrayList;import java.util.List;
@Document("vehicles") public class Vehicle {
 @Id private String id;private String ownerId,category,registrationNumber,model,status="PENDING",assignedDriverId,baseCityId,baseCity;private List<UploadedAsset> photos=new ArrayList<>(),documents=new ArrayList<>();
 public String getId(){return id;}public String getOwnerId(){return ownerId;}public void setOwnerId(String x){ownerId=x;}public String getCategory(){return category;}public void setCategory(String x){category=x;}public String getRegistrationNumber(){return registrationNumber;}public void setRegistrationNumber(String x){registrationNumber=x;}public String getModel(){return model;}public void setModel(String x){model=x;}public String getAssignedDriverId(){return assignedDriverId;}public void setAssignedDriverId(String x){assignedDriverId=x;}public String getBaseCityId(){return baseCityId;}public void setBaseCityId(String x){baseCityId=x;}public String getBaseCity(){return baseCity;}public void setBaseCity(String x){baseCity=x;}public String getStatus(){return status;}public void setStatus(String x){status=x;}public List<UploadedAsset> getPhotos(){return photos;}public void setPhotos(List<UploadedAsset> x){photos=x==null?new ArrayList<>():x;}public List<UploadedAsset> getDocuments(){return documents;}public void setDocuments(List<UploadedAsset> x){documents=x==null?new ArrayList<>():x;}
}